package mathutil

// BUG: off-by-one — should return 1 for n==0 and n==1
func Factorial(n int) int {
	if n <= 0 {
		return 0
	}
	result := 1
	for i := 2; i <= n; i++ {
		result *= i
	}
	return result
}

// BUG: wrong base case — GCD(0,b) should return b, not 0
func GCD(a, b int) int {
	for b != 0 {
		a, b = b, a%b
	}
	if a == 0 {
		return 0
	}
	return a
}

// BUG: wrong condition — should return false when n%i==0, not when n%i!=0
func IsPrime(n int) bool {
	if n < 2 {
		return false
	}
	for i := 2; i*i <= n; i++ {
		if n%i != 0 {
			return false
		}
	}
	return true
}

package mathutil

import "testing"

func TestFactorial(t *testing.T) {
	if Factorial(0) != 1 {
		t.Fatalf("Factorial(0) want 1 got %d", Factorial(0))
	}
	if Factorial(5) != 120 {
		t.Fatalf("Factorial(5) want 120 got %d", Factorial(5))
	}
}

func TestGCD(t *testing.T) {
	if GCD(12, 8) != 4 {
		t.Fatalf("GCD(12,8) want 4 got %d", GCD(12, 8))
	}
	if GCD(0, 5) != 5 {
		t.Fatalf("GCD(0,5) want 5 got %d", GCD(0, 5))
	}
}

func TestIsPrime(t *testing.T) {
	if !IsPrime(7) {
		t.Fatal("7 should be prime")
	}
	if IsPrime(9) {
		t.Fatal("9 should not be prime")
	}
}

func TestFactorialOne(t *testing.T) {
	if Factorial(1) != 1 {
		t.Fatalf("Factorial(1) want 1 got %d", Factorial(1))
	}
}

func TestIsPrimeTwo(t *testing.T) {
	if !IsPrime(2) {
		t.Fatal("2 should be prime")
	}
	if IsPrime(4) {
		t.Fatal("4 should not be prime")
	}
}
